function riskView(){const r=state.dashboard?.risk||{};return "<div class='page-head'><div><div class='eyebrow'>RISK CENTER · INDEPENDENT GATE</div><h1>Risk controls</h1><p class='lead'>These limits are stored separately from strategy logic and server-validated.</p></div></div><section class='card panel'><div class='form-grid'><div class='field'><label>Risk per trade %</label><input id='riskTrade' type='number' min='.01' max='10' step='.01' value='"+esc(r.risk_per_trade??1)+"'></div><div class='field'><label>Daily drawdown %</label><input id='riskDaily' type='number' min='.1' max='100' step='.1' value='"+esc(r.daily_drawdown??5)+"'></div><div class='field'><label>Total drawdown %</label><input id='riskTotal' type='number' min='.1' max='100' step='.1' value='"+esc(r.total_drawdown??10)+"'></div><div class='field'><label>Max open positions</label><input id='riskOpen' type='number' min='1' max='100' value='"+esc(r.max_open_positions??3)+"'></div></div><div class='control-row' style='margin-top:12px'><span>Kill switch</span><label><input id='riskKill' type='checkbox' "+(r.kill_switch?"checked":"")+"> <span class='status-chip "+(r.kill_switch?"lock":"good")+"'>"+(r.kill_switch?"ARMED":"OFF")+"</span></label></div><button class='btn primary' style='margin-top:12px' onclick='saveRisk()'>Save risk profile</button><div id='riskMsg' class='muted' style='font-size:10px;margin-top:8px'></div></section>";}

