function settingsView(){return "<div class='page-head'><div><div class='eyebrow'>PREFERENCES · OPERATOR PROFILE</div><h1>Settings</h1><p class='lead'>Change your visible profile, navigator image and command theme.</p></div></div><section class='card panel'><div class='eyebrow'>THEME MATRIX</div><h2 style='margin-top:6px'>Five interface identities.</h2><p class='lead'>Matrix is the green-tech mode. Switching theme does not change security or access logic.</p><div class='theme-grid' style='margin-top:14px'>"+themes.map(t=>"<button class='theme-btn "+(document.body.dataset.theme===t[0]?"active":"")+"' onclick=\"applyTheme('"+t[0]+"')\"><div class='swatch "+t[0]+"'></div><b>"+t[1]+"</b><span>"+t[2]+"</span></button>").join("")+"</div></section><div class='grid grid-2' style='margin-top:12px'><section class='card panel'><div class='eyebrow'>PROFILE</div><div class='form-grid' style='margin-top:12px'><div class='field full'><label>Display name</label><input id='setName' value='"+esc(state.user?.display_name||"")+"'></div><div class='field full'><label>Navigator / profile image</label><input id='avatarFile' type='file' accept='image/*' onchange='previewAvatar(event)'></div></div><div id='avatarPreview' style='margin-top:10px'><span class='avatar'>"+avatar()+"</span><span class='muted' style='margin-left:8px;font-size:10px'>Image is resized before saving.</span></div><button class='btn primary' style='margin-top:12px' onclick='saveSettings()'>Save profile</button><div id='setMsg' class='muted' style='font-size:10px;margin-top:8px'></div></section><section class='card panel'><div class='eyebrow'>IDENTITY STATUS</div><div class='control-row'><span>Email</span><b>"+(state.user?.email_verified?"VERIFIED":"PENDING")+"</b></div><div class='control-row'><span>Phone</span><b>"+(state.user?.phone_verified?"VERIFIED":"PENDING")+"</b></div><div class='control-row'><span>Role</span><b>"+esc((state.user?.role||"user").toUpperCase())+"</b></div><div class='control-row'><span>Access</span><b>"+(state.subscription?"PAID":"LOCKED")+"</b></div></section></div>";}

function securityView(){return "<div class='page-head'><div><div class='eyebrow'>SECURITY · CONTROL FABRIC</div><h1>Security Center</h1><p class='lead'>Operational security posture and boundaries between browser, auth, billing, risk and broker layers.</p></div></div><div class='grid grid-3'><article class='card panel'><div class='eyebrow'>IDENTITY</div><h2 style='margin-top:8px'>"+(state.user?.email_verified&&state.user?.phone_verified?"Verified":"Action required")+"</h2><p class='lead'>Email + phone verification is required before connector access.</p></article><article class='card panel'><div class='eyebrow'>SESSION</div><h2 style='margin-top:8px'>HttpOnly cookie</h2><p class='lead'>Signed session state is kept out of browser JavaScript.</p></article><article class='card panel'><div class='eyebrow'>EXECUTION</div><h2 class='danger' style='margin-top:8px'>Locked</h2><p class='lead'>No browser control can directly place a broker order.</p></article></div><section class='card panel' style='margin-top:12px'><div class='eyebrow'>BOUNDARY MAP</div>"+["Browser / Navigator","Authentication + verification","Subscription gate","Strategy proposal layer","Risk gate + kill switch","Broker connector boundary","Audit + ledger"].map((x,i)=>"<div class='control-row'><span>0"+(i+1)+" · "+x+"</span><b>"+(i<3?"ACCESS CONTROL":i===5?"BROKER GATE":"ISOLATED")+"</b></div>").join("")+"</section>";}

function notificationsView(){const ev=state.dashboard?.audit||[];return "<div class='page-head'><div><div class='eyebrow'>ACTIVITY · AUDIT EVENTS</div><h1>Notifications</h1><p class='lead'>Recent system events linked to your workspace.</p></div></div><section class='card panel'><div class='table-wrap'><table class='table'><thead><tr><th>EVENT</th><th>TIME</th></tr></thead><tbody>"+(ev.length?ev.map(e=>"<tr><td>"+esc(e.event_type)+"</td><td>"+new Date(e.created_at).toLocaleString()+"</td></tr>").join(""):"<tr><td colspan='2'><div class='empty'>No audit events yet.</div></td></tr>")+"</tbody></table></div></section>";}
