function adminView(){return "<div class='page-head'><div><div class='eyebrow'>ADMIN CONTROL · PRIVATE</div><h1>Operations desk</h1><p class='lead'>Payment approvals, support oversight and customer identity review. Admin access is role-gated server-side.</p></div><span class='status-chip warn'>ADMIN ONLY</span></div><div id='adminRoot'><div class='empty'><b>Loading operations data…</b></div></div>";}
function developerView(){return "<div class='page-head'><div><div class='eyebrow'>DEVELOPER OS · PRIVATE</div><h1>Fintech control plane</h1><p class='lead'>Application-level controls, data inventory, AI configuration status and editable feature settings. Source changes remain governed through GitHub.</p></div><span class='status-chip warn'>DEVELOPER ONLY</span></div><div id='devRoot'><div class='empty'><b>Loading control plane…</b></div></div>";}

async function refreshUser(){const d=await api("/api/auth/me");state.user=d.user;if(state.user?.theme)setTheme(state.user.theme);}
async function loadDashboard(){if(!state.user)return;try{const d=await api("/api/dashboard");state.dashboard=d;state.subscription=d.subscription||null}catch(e){if(e.status===401){state.user=null;state.dashboard=null;state.subscription=null;}}}
function protectedRoute(){return ["dashboard","bots","ai","watchlist","analytics","risk","accounts","billing","support","settings","security","notifications","profile","admin","developer","verify"].includes(state.route);}
async function render(){
  state.route=(location.hash||"#/home").slice(2)||"home";
  const publicRoute=["home","login","signup"].includes(state.route);

  // Public pages render immediately. A failed/cold API must never leave the whole
  // application blank while the browser waits for authentication state.
  if(publicRoute){
    const publicHtml=state.route==="home"?homeView():authView(state.route);
    $("#app").innerHTML=publicHtml;
    bind();
    postRender().catch(e=>toast(e.message));
    refreshUser().then(()=>{
      if(state.user && state.route==="home") render();
    }).catch(()=>{});
    return;
  }

  try{await refreshUser()}catch{}
  if(!state.user&&protectedRoute()&&state.route!=="billing"){
    if(state.route==="verify"){location.hash="#/login";return}
    location.hash="#/login";return;
  }
  if(state.user)await loadDashboard();

  let html="";
  if(state.route==="verify")html=verifyView();
  else {
    switch(state.route){
      case "home":html=state.user?shell(dashboardView()):homeView();break;
      case "dashboard":html=shell(dashboardView());break;
      case "bots":html=shell(botsView());break;
      case "ai":html=shell(aiView());break;
      case "markets":html=shell(marketView("markets"));break;
      case "watchlist":html=shell(marketView("watchlist"));break;
      case "analytics":html=shell(analyticsView());break;
      case "billing":html=shell(billingView());break;
      case "accounts":html=shell(accountsView());break;
      case "risk":html=shell(riskView());break;
      case "support":html=shell(supportView());break;
      case "settings":html=shell(settingsView());break;
      case "security":html=shell(securityView());break;
      case "notifications":html=shell(notificationsView());break;
      case "profile":html=shell(profileView());break;
      case "admin":html=shell(state.user?.role==="admin"?adminView():"<div class='empty'><b>Restricted control area</b><span>Admin email allowlist required.</span></div>");break;
      case "developer":html=shell(state.user?.role==="developer"?developerView():"<div class='empty'><b>Developer control area</b><span>Developer email allowlist required.</span></div>");break;
      default:html=shell(dashboardView());
    }
  }
  $("#app").innerHTML=html;
  bind();
  postRender().catch(e=>toast(e.message));
}
function bind(){const b=$("#profileBtn");if(b)b.onclick=()=>$("#profileMenu")?.classList.toggle("show");const f=$("#authForm");if(f)f.onsubmit=handleAuth;const ap=$("#aiPrompt");if(ap)ap.onkeydown=(e)=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();sendAI()}};}
async function handleAuth(e){
  e.preventDefault();const fd=new FormData(e.target),signup=state.route==="signup",payload=Object.fromEntries(fd.entries());
  try{const d=await api(signup?"/api/auth/register":"/api/auth/login",{method:"POST",body:JSON.stringify(payload)});state.user=d.user;if(signup){if(d.developmentEmailCode){$("#authMsg").textContent="Development email code: "+d.developmentEmailCode}location.hash="#/verify"}else location.hash="#/dashboard";toast("Secure session established")}catch(err){$("#authMsg").textContent=err.message;$("#authMsg").className="danger";}
}
async function logout(){await api("/api/auth/logout",{method:"POST"});state.user=null;state.dashboard=null;state.subscription=null;state.aiHistory=[];location.hash="#/home";toast("Signed out securely");}
async function verifyEmail(){try{await api("/api/auth/verify/email",{method:"POST",body:JSON.stringify({code:$("#emailCode").value})});toast("Email verified");await refreshUser();await render()}catch(e){$("#verifyMsg").textContent=e.message}}
async function verifyPhone(){try{await api("/api/auth/verify/phone",{method:"POST",body:JSON.stringify({code:$("#phoneCode").value})});toast("Phone verified");await refreshUser();await render()}catch(e){$("#verifyMsg").textContent=e.message}}
async function resendCodes(){try{const d=await api("/api/auth/resend",{method:"POST"});toast("Verification codes requested");if(d.email&&d.email!=="sent"){const x=$("#devCode");x.style.display="inline-flex";x.textContent="Development email code: "+d.email}}catch(e){toast(e.message)}}
async function createBot(){try{const d=await api("/api/dashboard/bots",{method:"POST",body:JSON.stringify({strategyCode:$("#botTemplate").value,symbol:$("#botSymbol").value,timeframe:$("#botTimeframe").value,templateCode:$("#botTemplate").value})});toast("Bot instance registered: "+d.id);location.hash="#/dashboard"}catch(e){$("#botMsg").textContent=e.message}}
async function sendAI(){const p=$("#aiPrompt")?.value.trim();if(!p)return;state.aiHistory.push({role:"user",text:p});renderChat();$("#aiPrompt").value="";try{const d=await api("/api/ai/chat",{method:"POST",body:JSON.stringify({prompt:p,history:state.aiHistory.slice(-12)})});state.aiHistory.push({role:"assistant",text:d.text});renderChat()}catch(e){state.aiHistory.push({role:"assistant",text:"System response: "+e.message});renderChat()}}
function renderChat(){const r=$("#chatMessages");if(!r)return;r.innerHTML=state.aiHistory.map(m=>"<div class='msg "+(m.role==="assistant"?"ai":"user")+"'><div class='who'>"+(m.role==="assistant"?"KING AI":"YOU")+"</div>"+esc(m.text).replace(/\\n/g,"<br>")+"</div>").join("");r.scrollTop=r.scrollHeight}
function mountTV(id,symbol,interval,watchlist=[]){const h=document.getElementById(id);if(!h)return;h.innerHTML="<div style='height:100%;width:100%'></div>";const s=document.createElement("script");s.type="text/javascript";s.async=true;s.src="https://s3.tradingview.com/external-embedding/embed-widget-advanced-chart.js";s.innerHTML=JSON.stringify({autosize:true,symbol,interval,timezone:"exchange",theme:"dark",style:"1",withdateranges:true,hide_side_toolbar:false,allow_symbol_change:true,save_image:false,locale:"en",calendar:false,hide_top_toolbar:false,hide_legend:false,hide_volume:false,show_popup_button:true,support_host:"https://www.tradingview.com",watchlist});h.firstElementChild.appendChild(s)}
function selectSymbol(s){state.selectedSymbol=s;render()}
async function loadAnalytics(){try{const d=await api("/api/analytics"),s=d.summary||{},r=$("#analyticsRoot");r.className="";r.innerHTML="<div class='kpis'><div class='kpi glass'><span>RECORDED TRADES</span><strong>"+s.trades+"</strong><small>Server ledger</small></div><div class='kpi glass'><span>VERIFIED P&L</span><strong>"+Number(s.pnl||0).toFixed(2)+"</strong><small>Ledger currency</small></div><div class='kpi glass'><span>WIN RATE</span><strong>"+Number(s.win_rate||0).toFixed(2)+"%</strong><small>Closed trades</small></div><div class='kpi glass'><span>AVERAGE P&L</span><strong>"+Number(s.avg_pnl||0).toFixed(2)+"</strong><small>Recorded trades</small></div></div><div class='grid grid-2'><section class='card panel'><div class='eyebrow'>BY SYMBOL</div><div class='table-wrap' style='margin-top:10px'><table class='table'><thead><tr><th>SYMBOL</th><th>TRADES</th><th>P&L</th></tr></thead><tbody>"+(d.bySymbol?.length?d.bySymbol.map(x=>"<tr><td>"+esc(x.symbol)+"</td><td>"+x.trades+"</td><td>"+Number(x.pnl||0).toFixed(2)+"</td></tr>").join(""):"<tr><td colspan='3'>No verified trade records.</td></tr>")+"</tbody></table></div></section><section class='card panel'><div class='eyebrow'>RECENT TRADES</div><div class='table-wrap' style='margin-top:10px'><table class='table'><thead><tr><th>TIME</th><th>SYMBOL</th><th>SIDE</th><th>P&L</th><th>STATUS</th></tr></thead><tbody>"+(d.recent?.length?d.recent.map(x=>"<tr><td>"+new Date(x.closed_at||x.opened_at).toLocaleString()+"</td><td>"+esc(x.symbol)+"</td><td>"+esc(x.side)+"</td><td>"+Number(x.pnl||0).toFixed(2)+"</td><td>"+esc(x.status)+"</td></tr>").join(""):"<tr><td colspan='5'>No verified trade records.</td></tr>")+"</tbody></table></div></section></div>"}catch(e){const r=$("#analyticsRoot");if(r)r.innerHTML="<div class='empty'><b>Analytics locked</b><span>"+esc(e.message)+"</span></div>"}}
async function loadBilling(){try{const d=await api("/api/subscriptions");state.plans=d.plans||[];$("#plansRoot").innerHTML=state.plans.map((p,i)=>"<article class='plan card "+(i===1?"popular":"")+"'>"+(i===1?"<div class='ribbon'>DESK CHOICE</div>":"")+"<div class='eyebrow'>"+esc(p.code)+"</div><h2 style='margin-top:7px'>"+esc(p.name)+"</h2><div class='price'>$"+Number(p.monthlyUsd).toLocaleString()+"<span class='per'> / month</span></div><ul class='feature-list'>"+p.features.map(f=>"<li>"+esc(f)+"</li>").join("")+"</ul><button class='btn "+(i===1?"primary":"")+"' style='width:100%' onclick=\"pickPlan('"+p.code+"')\">Select "+esc(p.name)+"</button></article>").join("");$("#payPlan").innerHTML=state.plans.map(p=>"<option value='"+p.code+"'>"+esc(p.name)+" · $"+p.monthlyUsd+"/mo</option>").join("");$("#paymentHistory").innerHTML=d.requests?.length?"<table class='table'><thead><tr><th>PLAN</th><th>METHOD</th><th>REFERENCE</th><th>STATUS</th></tr></thead><tbody>"+d.requests.map(x=>"<tr><td>"+x.plan_code+"</td><td>"+x.method+"</td><td>"+esc(x.reference)+"</td><td><span class='status-chip'>"+x.status.toUpperCase()+"</span></td></tr>").join("")+"</tbody></table>":"<div class='empty'><b>No payment requests</b><span>Submit one above for administrator review.</span></div>"}catch(e){$("#plansRoot").innerHTML="<div class='empty'><b>"+esc(e.message)+"</b></div>"}}
function pickPlan(code){const s=$("#payPlan");if(s){s.value=code;s.scrollIntoView({behavior:"smooth",block:"center"})}}
async function submitPayment(){try{const d=await api("/api/subscriptions/payment-request",{method:"POST",body:JSON.stringify({planCode:$("#payPlan").value,method:$("#payMethod").value,reference:$("#payReference").value.trim()})});$("#payMsg").textContent=d.message;await loadBilling()}catch(e){$("#payMsg").textContent=e.message}}
async function loadAccounts(){try{const d=await api("/api/accounts");$("#accountsRoot").innerHTML=d.accounts?.length?"<div class='table-wrap'><table class='table'><thead><tr><th>CONNECTOR</th><th>LABEL</th><th>ACCOUNT ID</th><th>STATUS</th></tr></thead><tbody>"+d.accounts.map(a=>"<tr><td>"+esc(a.provider)+"</td><td>"+esc(a.label)+"</td><td>"+esc(a.external_account_id||"—")+"</td><td>"+esc(a.status).toUpperCase()+"</td></tr>").join("")+"</tbody></table></div>":"<div class='empty'><b>No connector records.</b><span>Paid, verified workspaces can register an account connector.</span></div>"}catch(e){$("#accountsRoot").innerHTML="<div class='empty'><b>"+esc(e.message)+"</b></div>"}}
async function registerAccount(){try{const d=await api("/api/accounts",{method:"POST",body:JSON.stringify({provider:$("#acctProvider").value,label:$("#acctLabel").value,externalAccountId:$("#acctId").value})});$("#acctMsg").textContent=d.message;await loadAccounts()}catch(e){$("#acctMsg").textContent=e.message}}
async function saveRisk(){try{const d=await api("/api/dashboard/risk",{method:"PATCH",body:JSON.stringify({riskPerTrade:Number($("#riskTrade").value),dailyDrawdown:Number($("#riskDaily").value),totalDrawdown:Number($("#riskTotal").value),maxOpenPositions:Number($("#riskOpen").value),killSwitch:$("#riskKill").checked})});state.dashboard.risk=d.risk;$("#riskMsg").textContent="Risk profile saved.";toast("Risk controls saved")}catch(e){$("#riskMsg").textContent=e.message}}
async function loadTickets(){try{const d=await api("/api/support");$("#ticketsRoot").innerHTML=d.tickets?.length?d.tickets.map(t=>"<article class='ticket'><div class='ticket-head'><h3>"+esc(t.subject)+"</h3><span class='status-chip'>"+esc(t.status).toUpperCase()+"</span></div><p>"+esc(t.message)+"</p><div class='panel-meta' style='margin-top:8px'>"+new Date(t.created_at).toLocaleString()+"</div></article>").join(""):"<div class='empty'><b>No tickets.</b><span>Your support requests will appear here.</span></div>"}catch(e){$("#ticketsRoot").innerHTML="<div class='empty'>"+esc(e.message)+"</div>"}}
async function createTicket(){try{await api("/api/support",{method:"POST",body:JSON.stringify({subject:$("#ticketSubject").value,message:$("#ticketMessage").value})});$("#ticketMsg").textContent="Ticket created.";$("#ticketSubject").value="";$("#ticketMessage").value="";loadTickets()}catch(e){$("#ticketMsg").textContent=e.message}}
async function saveSettings(){try{const p={displayName:$("#setName").value,theme:document.body.dataset.theme};if(state._avatarData)p.avatarUrl=state._avatarData;const d=await api("/api/settings",{method:"PATCH",body:JSON.stringify(p)});state.user={...state.user,...d.user};$("#setMsg").textContent="Profile preferences saved.";toast("Settings saved")}catch(e){$("#setMsg").textContent=e.message}}
async function applyTheme(t){setTheme(t);if(state.user){try{await saveSettings()}catch{}}await render()}
function previewAvatar(e){const f=e.target.files?.[0];if(!f)return;const img=new Image(),reader=new FileReader();reader.onload=()=>{img.onload=()=>{const c=document.createElement("canvas"),m=160,scale=Math.min(1,m/img.width,m/img.height);c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext("2d").drawImage(img,0,0,c.width,c.height);state._avatarData=c.toDataURL("image/webp",.82);$("#avatarPreview").innerHTML="<span class='avatar' style='width:54px;height:54px'><img src='"+state._avatarData+"' alt='Preview'></span>"};img.src=reader.result};reader.readAsDataURL(f)}
async function loadAdmin(){try{const o=await api("/api/admin/overview"),p=await api("/api/admin/payments"),t=await api("/api/admin/tickets");$("#adminRoot").innerHTML="<div class='admin-kpis'><div class='kpi card'><span>USERS</span><strong>"+o.counts.users+"</strong></div><div class='kpi card'><span>PENDING PAYMENTS</span><strong>"+o.counts.pendingPayments+"</strong></div><div class='kpi card'><span>OPEN TICKETS</span><strong>"+o.counts.openTickets+"</strong></div><div class='kpi card'><span>ACTIVE PLANS</span><strong>"+o.counts.activeSubscriptions+"</strong></div></div><div class='grid grid-2' style='margin-top:12px'><section class='card panel'><div class='eyebrow'>PAYMENT APPROVALS</div><div class='table-wrap' style='margin-top:10px'><table class='table'><thead><tr><th>USER</th><th>PLAN</th><th>REF</th><th>ACTION</th></tr></thead><tbody>"+p.payments.map(x=>"<tr><td>"+esc(x.email)+"</td><td>"+x.plan_code+"</td><td>"+esc(x.reference)+"</td><td>"+(x.status==="pending"?"<button class='btn small primary' onclick=\"approvePayment('"+x.id+"')\">Approve</button> <button class='btn small danger' onclick=\"rejectPayment('"+x.id+"')\">Reject</button>":"<span class='status-chip'>"+x.status.toUpperCase()+"</span>")+"</td></tr>").join("")+"</tbody></table></div></section><section class='card panel'><div class='eyebrow'>SUPPORT OPERATIONS</div><div class='support-list' style='margin-top:10px'>"+(t.tickets.map(x=>"<article class='ticket'><div class='ticket-head'><h3>"+esc(x.subject)+"</h3><span class='status-chip'>"+esc(x.status).toUpperCase()+"</span></div><p>"+esc(x.email)+" · "+esc(x.message)+"</p><div class='action-row'><button class='btn small' onclick=\"updateTicket('"+x.id+"','resolved')\">Mark resolved</button></div></article>").join("")||"<div class='empty'>No support tickets.</div>")+"</div></section></div><section class='card panel' style='margin-top:12px'><div class='eyebrow'>CUSTOMER IDENTITIES</div><div class='table-wrap' style='margin-top:10px'><table class='table'><thead><tr><th>NAME</th><th>EMAIL</th><th>ROLE</th><th>VERIFY</th></tr></thead><tbody>"+o.recentUsers.map(u=>"<tr><td>"+esc(u.display_name)+"</td><td>"+esc(u.email)+"</td><td>"+u.role.toUpperCase()+"</td><td>"+(u.email_verified?"E":"—")+" / "+(u.phone_verified?"P":"—")+"</td></tr>").join("")+"</tbody></table></div></section>"}catch(e){$("#adminRoot").innerHTML="<div class='empty'><b>"+esc(e.message)+"</b></div>"}}
async function approvePayment(id){try{await api("/api/admin/payments/"+id+"/approve",{method:"POST"});toast("Payment approved and subscription activated.");loadAdmin()}catch(e){toast(e.message)}}
async function rejectPayment(id){try{await api("/api/admin/payments/"+id+"/reject",{method:"POST"});toast("Payment request rejected.");loadAdmin()}catch(e){toast(e.message)}}
async function updateTicket(id,s){try{await api("/api/admin/tickets/"+id,{method:"PATCH",body:JSON.stringify({status:s})});loadAdmin()}catch(e){toast(e.message)}}
async function loadDeveloper(){try{const d=await api("/api/developer/overview"),root=$("#devRoot");root.innerHTML="<div class='kpis'><div class='kpi card'><span>VERSION</span><strong>"+d.version+"</strong></div><div class='kpi card'><span>GEMINI</span><strong class='"+(d.gemini.configured?"good":"danger")+"'>"+(d.gemini.configured?"READY":"KEY REQUIRED")+"</strong><small>"+esc(d.gemini.model)+"</small></div><div class='kpi card'><span>TRADING</span><strong class='danger'>"+(d.tradingEnabled?"ENABLED":"LOCKED")+"</strong></div><div class='kpi card'><span>NODE</span><strong>"+esc(d.nodeEnv)+"</strong></div></div><div class='grid grid-2' style='margin-top:12px'><section class='card panel'><div class='eyebrow'>DATABASE INVENTORY</div>"+Object.entries(d.counts).map(([k,v])=>"<div class='control-row'><span>"+k+"</span><b>"+v+"</b></div>").join("")+"</section><section class='card panel'><div class='eyebrow'>RUNTIME CONTROLS</div>"+["maintenance_mode","default_theme","support_banner","ai_agent_mode","market_banner"].map(k=>"<div class='control-row'><span>"+k+"</span><button class='btn small' onclick=\"setDevSetting('"+k+"')\">Edit</button></div>").join("")+"<div class='control-row'><span>Admin allowlist</span><b>CONFIGURED</b></div><div class='control-row'><span>Developer allowlist</span><b>CONFIGURED</b></div></section></div><section class='card panel' style='margin-top:12px'><div class='eyebrow'>ENGINEERING BOUNDARY</div><p class='lead'>GitHub governs source, Render governs deployment and this control plane governs application-level settings. Live trading remains an environment-level capability.</p></section>"}catch(e){$("#devRoot").innerHTML="<div class='empty'><b>"+esc(e.message)+"</b></div>"}}
async function setDevSetting(key){const v=prompt("New value for "+key);if(v===null)return;try{await api("/api/developer/settings/"+key,{method:"PUT",body:JSON.stringify({value:v})});toast("Developer setting updated.");loadDeveloper()}catch(e){toast(e.message)}}
async function postRender(){if(state.route==="markets"||state.route==="watchlist")mountTV("tvChart",state.selectedSymbol,state.route==="watchlist"?"60":"15",symbols.map(s=>s[0]));if(state.route==="analytics")loadAnalytics();if(state.route==="billing")loadBilling();if(state.route==="accounts")loadAccounts();if(state.route==="support")loadTickets();if(state.route==="admin"&&state.user?.role==="admin")loadAdmin();if(state.route==="developer"&&state.user?.role==="developer")loadDeveloper();if(state.route==="verify"){const d=await api("/api/auth/verify/status");if(d.emailVerified&&d.phoneVerified){toast("Identity verified");location.hash="#/dashboard"}}}
A.logout=logout;A.verifyEmail=verifyEmail;A.verifyPhone=verifyPhone;A.resendCodes=resendCodes;A.createBot=createBot;A.sendAI=sendAI;A.selectSymbol=selectSymbol;A.pickPlan=pickPlan;A.submitPayment=submitPayment;A.registerAccount=registerAccount;A.saveRisk=saveRisk;A.createTicket=createTicket;A.applyTheme=applyTheme;A.previewAvatar=previewAvatar;A.saveSettings=saveSettings;A.approvePayment=approvePayment;A.rejectPayment=rejectPayment;A.updateTicket=updateTicket;A.setDevSetting=setDevSetting;
const st=localStorage.getItem("bk_theme");if(st)setTheme(st);window.addEventListener("hashchange",render);render();
